package com.madar.files;

import android.app.*;
import android.content.*;
import android.graphics.Color;
import android.net.Uri;
import android.os.*;
import android.view.*;
import android.widget.*;
import androidx.media3.common.*;
import androidx.media3.exoplayer.ExoPlayer;
import androidx.media3.ui.PlayerView;
import java.io.*;
import java.util.*;

@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
public class PlayerActivity extends Activity {
 private ExoPlayer player;private PlayerView view;private File file,subtitle;private String key;private long loopA=-1,loopB=-1;private final Handler timer=new Handler(Looper.getMainLooper());private TextView status;private float speed=1,pitch=1;private boolean locked;private LinearLayout toolbar;private FrameLayout stage;private View cover;private long position;private boolean resume=true;
 @Override public void onCreate(Bundle state){super.onCreate(state);try{
  file=new File(getIntent().getStringExtra("path")).getCanonicalFile();if(!file.isFile()||!(file.getPath().startsWith(getCacheDir().getCanonicalPath()+"/")||file.getPath().startsWith(FilesUtil.directory(this).getCanonicalPath()+"/")))throw new IOException("ملف غير صالح");
  key="position_"+file.getName();position=getSharedPreferences("player",0).getLong(key,0);
  LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(24,34,34));root.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets b=i.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(b.left,b.top,b.right,b.bottom);return i;});
  stage=new FrameLayout(this);view=new PlayerView(this);stage.addView(view,new FrameLayout.LayoutParams(-1,-1));root.addView(stage,new LinearLayout.LayoutParams(-1,0,1));
  status=new TextView(this);status.setTextColor(Color.WHITE);status.setPadding(20,8,20,8);status.setText("مدار · "+getIntent().getStringExtra("title"));root.addView(status);
  HorizontalScrollView scroll=new HorizontalScrollView(this);toolbar=new LinearLayout(this);scroll.addView(toolbar);root.addView(scroll);
  button("رجوع",()->finish());button("السرعة والصوت",this::sound);button("ترجمة SRT / VTT",()->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE),32));button("حجم الترجمة",()->{if(view.getSubtitleView()!=null){final String[] labels={"صغير","متوسط","كبير"};new AlertDialog.Builder(this).setItems(labels,(d,n)->view.getSubtitleView().setFractionalTextSize(new float[]{.04f,.055f,.075f}[n])).show();}});
  button("بداية التكرار A",()->{loopA=player.getCurrentPosition();loopB=-1;status.setText("بداية التكرار: "+stamp(loopA));});button("نهاية التكرار B",()->{long b=player.getCurrentPosition();if(loopA<0||b<=loopA){toast("حدد البداية أولًا ثم نهاية بعدها");return;}loopB=b;player.seekTo(loopA);status.setText("تكرار "+stamp(loopA)+" — "+stamp(loopB));});button("إلغاء التكرار",()->{loopA=loopB=-1;status.setText("تم إلغاء التكرار");});
  button("علامة مرجعية",()->{getSharedPreferences("player",0).edit().putLong("mark_"+file.getName(),player.getCurrentPosition()).apply();toast("حُفظت العلامة");});button("إلى العلامة",()->player.seekTo(getSharedPreferences("player",0).getLong("mark_"+file.getName(),0)));
  button("تغطية يدوية",this::cover);button("قفل اللمس",()->{locked=!locked;view.setUseController(!locked);for(int i=0;i<toolbar.getChildCount();i++){View b=toolbar.getChildAt(i);if(b instanceof Button&&!((Button)b).getText().toString().contains("قفل"))b.setEnabled(!locked);}toast(locked?"اللمس مقفل؛ اضغط قفل اللمس لفتحه":"تم فتح اللمس");});
  setContentView(root);root.requestApplyInsets();buildPlayer();timer.post(tick);
 }catch(Exception e){toast("تعذر تشغيل الملف: "+e.getMessage());finish();}}
 private void button(String title,Runnable action){Button b=new Button(this);b.setText(title);b.setOnClickListener(v->action.run());toolbar.addView(b);}
 private void buildPlayer(){if(player!=null)player.release();player=new ExoPlayer.Builder(this).build();view.setPlayer(player);MediaItem.Builder media=new MediaItem.Builder().setUri(Uri.fromFile(file));if(subtitle!=null)media.setSubtitleConfigurations(Collections.singletonList(new MediaItem.SubtitleConfiguration.Builder(Uri.fromFile(subtitle)).setMimeType(subtitle.getName().endsWith(".vtt")?MimeTypes.TEXT_VTT:MimeTypes.APPLICATION_SUBRIP).setLanguage("ar").setSelectionFlags(C.SELECTION_FLAG_DEFAULT).build()));player.setMediaItem(media.build());player.setPlaybackParameters(new PlaybackParameters(speed,pitch));player.seekTo(position);player.addListener(new Player.Listener(){@Override public void onPlayerError(PlaybackException error){toast("تعذر تشغيل هذا الترميز على الجهاز");}});player.prepare();player.setPlayWhenReady(resume);}
 private final Runnable tick=new Runnable(){public void run(){if(player!=null&&loopB>loopA&&loopA>=0&&player.getCurrentPosition()>=loopB)player.seekTo(loopA);timer.postDelayed(this,150);}};
 private void sound(){LinearLayout layout=new LinearLayout(this);layout.setPadding(30,10,30,10);layout.setOrientation(1);slider(layout,"سرعة التشغيل",25,200,(int)(speed*100),n->{speed=n/100f;player.setPlaybackParameters(new PlaybackParameters(speed,pitch));});slider(layout,"طبقة الصوت",50,200,(int)(pitch*100),n->{pitch=n/100f;player.setPlaybackParameters(new PlaybackParameters(speed,pitch));});slider(layout,"مستوى الصوت",0,100,(int)(player.getVolume()*100),n->player.setVolume(n/100f));new AlertDialog.Builder(this).setTitle("الصوت أثناء المشاهدة").setView(layout).setPositiveButton("تم",null).show();}
 interface Change{void set(int n);}private void slider(LinearLayout parent,String name,int min,int max,int initial,Change change){TextView title=new TextView(this);title.setText(name+" · "+initial+"%");parent.addView(title);SeekBar bar=new SeekBar(this);bar.setMin(min);bar.setMax(max);bar.setProgress(initial);bar.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onProgressChanged(SeekBar b,int n,boolean user){title.setText(name+" · "+n+"%");if(user)change.set(n);}public void onStartTrackingTouch(SeekBar b){}public void onStopTrackingTouch(SeekBar b){}});parent.addView(bar);}
 private void cover(){if(cover!=null){stage.removeView(cover);cover=null;return;}TextView block=new TextView(this);block.setText("اسحب لتحريك التغطية\nاسحب الزاوية لتغيير الحجم");block.setTextColor(Color.WHITE);block.setGravity(Gravity.CENTER);block.setBackgroundColor(Color.rgb(45,51,49));FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(220,220);p.leftMargin=40;p.topMargin=40;stage.addView(block,p);cover=block;block.setOnTouchListener(new View.OnTouchListener(){float x,y;int left,top,w,h;boolean resize;public boolean onTouch(View v,android.view.MotionEvent e){if(locked)return true;FrameLayout.LayoutParams a=(FrameLayout.LayoutParams)v.getLayoutParams();if(e.getAction()==0){x=e.getRawX();y=e.getRawY();left=a.leftMargin;top=a.topMargin;w=a.width;h=a.height;resize=e.getX()>w-60&&e.getY()>h-60;return true;}if(e.getAction()==2){int dx=(int)(e.getRawX()-x),dy=(int)(e.getRawY()-y);if(resize){a.width=Math.max(80,Math.min(stage.getWidth()-left,w+dx));a.height=Math.max(80,Math.min(stage.getHeight()-top,h+dy));}else{a.leftMargin=Math.max(0,Math.min(stage.getWidth()-w,left+dx));a.topMargin=Math.max(0,Math.min(stage.getHeight()-h,top+dy));}v.setLayoutParams(a);return true;}return true;}});toast("تغطية يدوية للمشاهدة فقط؛ لا تتتبع الأشخاص");}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request!=32||result!=RESULT_OK||data==null||data.getData()==null)return;try{String name="";try(android.database.Cursor c=getContentResolver().query(data.getData(),new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}String ext=name.toLowerCase(Locale.ROOT).endsWith(".vtt")?".vtt":".srt";File f=File.createTempFile("subtitle_",ext,getCacheDir());try(InputStream in=getContentResolver().openInputStream(data.getData());OutputStream out=new FileOutputStream(f)){byte[] b=new byte[8192];int n,total=0;while((n=in.read(b))!=-1){total+=n;if(total>4*1024*1024)throw new IOException("ملف الترجمة كبير جدًا");out.write(b,0,n);}}position=player.getCurrentPosition();resume=player.getPlayWhenReady();File old=subtitle;subtitle=f;buildPlayer();if(old!=null)old.delete();toast("تم تحميل الترجمة");}catch(Exception e){toast("تعذر فتح الترجمة");}}
 private String stamp(long ms){return String.format(Locale.US,"%d:%02d",ms/60000,ms/1000%60);}private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
 @Override protected void onPause(){super.onPause();if(player!=null){position=player.getCurrentPosition();resume=player.getPlayWhenReady();getSharedPreferences("player",0).edit().putLong(key,position).apply();player.pause();}}
 @Override protected void onResume(){super.onResume();if(player!=null)player.setPlayWhenReady(resume);}
 @Override protected void onDestroy(){timer.removeCallbacksAndMessages(null);if(player!=null){view.setPlayer(null);player.release();}if(subtitle!=null)subtitle.delete();super.onDestroy();}
}
